const raw = String($input.first().json.domain || '').trim().toLowerCase()
  .replace(/^[a-z]+:\/\//, '').replace(/[\/?#].*$/, '').replace(/\.$/, '');
const re = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
if (!re.test(raw)) {
  throw new Error('Invalid domain "' + raw + '". Provide a bare domain such as example.com.');
}
return [{ json: { domain: raw } }];

const domain = $('Validate Domain').first().json.domain;
const scopes = $input.all().map((i) => i.json).filter((j) => j && j.domain && j.active !== false).map((j) => String(j.domain).toLowerCase());
const matched = scopes.find((s) => domain === s || domain.endsWith('.' + s));
return [{ json: { domain, in_scope: !!matched, matched_scope: matched || null } }];

const sc = $('Scope Check').first().json;
const domain = sc.domain;
if (!sc.in_scope) {
  throw new Error('REFUSED: ' + domain + ' is not in the authorised scope list (MongoDB collection "scope"). The operator must add it with scripts/add-scope.sh after confirming written authorisation.');
}
const ap = $input.all().map((i) => i.json).find((j) => j && j.domain === domain);
const now = new Date();
if (!ap || ap.status !== 'granted' || !ap.expires_at || new Date(ap.expires_at) <= now) {
  throw new Error('REFUSED: no valid user approval for ' + domain + '. The user must reply exactly "APPROVE ' + domain + '". Approvals are single-use and expire after 30 minutes.');
}
const scan_id = 'scan-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
return [{ json: {
  domain, scan_id,
  approved_at: ap.granted_at || now.toISOString(),
  approval_session: ap.session_id || '',
  matched_scope: sc.matched_scope,
  status: 'consumed',
  consumed_at: now.toISOString(),
} }];

const g = $('Gate').first().json;
return [{ json: {
  scan_id: g.scan_id,
  root_domain: g.domain,
  status: 'running',
  stage: 'discovery',
  started_at: g.consumed_at,
  approved_at: g.approved_at,
  approval_session: g.approval_session,
  matched_scope: g.matched_scope,
} }];

const ssh = $('Run Discovery').first().json;
const g = $('Gate').first().json;
if (ssh.code !== undefined && ssh.code !== 0) {
  throw new Error('Discovery script failed (exit ' + ssh.code + '): ' + String(ssh.stderr || '').slice(-800));
}
let out;
try { out = JSON.parse(ssh.stdout); }
catch (e) { throw new Error('Discovery output was not valid JSON: ' + String(ssh.stdout || '').slice(0, 300) + ' | stderr: ' + String(ssh.stderr || '').slice(-500)); }

const existing = new Map($input.all().map((i) => i.json).filter((j) => j && j.host).map((j) => [j.host, j]));
const dnsBy = new Map((out.dns || []).map((d) => [d.host, d]));
const liveBy = new Map((out.live || []).map((l) => [l.host, l]));
const now = new Date().toISOString();
const hosts = Array.from(new Set((out.subdomains || []).map((h) => String(h).toLowerCase())));

const docs = hosts.map((host) => {
  const d = dnsBy.get(host) || { a: [], aaaa: [], cname: [], rcode: '' };
  const resolved = (d.a.length + d.aaaa.length) > 0;
  const lv = liveBy.get(host);
  const prev = existing.get(host);
  return { json: {
    host,
    root_domain: g.domain,
    first_seen: prev && prev.first_seen ? prev.first_seen : now,
    last_seen: now,
    last_scan_id: g.scan_id,
    status: lv ? 'live' : (resolved ? 'resolved' : 'unresolved'),
    dns: {
      a: [...d.a].sort(), aaaa: [...d.aaaa].sort(), cname: [...d.cname].sort(),
      rcode: d.rcode, resolved,
      dangling_cname: !resolved && d.cname.length > 0,
      updated_at: now,
    },
    discovery: { live_probe: lv ? lv.services : [], scan_id: g.scan_id, updated_at: now },
    _is_new: !prev,
  } };
});
return docs;

const g = $('Gate').first().json;
const out = JSON.parse($('Run Discovery').first().json.stdout);
const items = $('Normalize & Merge').all().map((i) => i.json);
const now = new Date().toISOString();
const live = items.filter((i) => i.status === 'live');
const summary = {
  ok: true,
  stage: 'discovery',
  scan_id: g.scan_id,
  domain: g.domain,
  subdomains_found: items.length,
  new_assets: items.filter((i) => i._is_new).length,
  already_known: items.filter((i) => !i._is_new).length,
  live_hosts: live.length,
  resolved_not_live: items.filter((i) => i.status === 'resolved').length,
  unresolved: items.filter((i) => i.status === 'unresolved').length,
  dangling_cname_candidates: items.filter((i) => i.dns.dangling_cname).map((i) => i.host).slice(0, 10),
  source_counts: out.tools,
  bruteforce: out.bruteforce,
  sample_live_hosts: live.map((i) => i.host).slice(0, 10),
  warnings: out.warnings || [],
  next_step: live.length ? 'run_fingerprinting' : 'No live hosts: stop and report.',
};
return [{ json: { scan_id: g.scan_id, stage: 'discovery_done', updated_at: now, discovery_summary: summary } }];
